from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(s: str, depth: int) -> int:
        if not s:
            return depth
        if s[0] == '(':
            return max_depth(s[1:], depth + 1)
        elif s[0] == ')':
            return max_depth(s[1:], depth - 1)
        else:
            return max_depth(s[1:], depth)

    result = []
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            depth = 1
            j = i + 1
            while j < len(paren_string) and paren_string[j] != '(' and paren_string[j] != ')':
                j += 1
            result.append(max_depth(paren_string[i:j], 1))
            i = j
        else:
            i += 1

    return result
```

